import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.e4u2V5E7.js";const y=JSON.parse('{"title":"Typescript","description":"Typescript reference documentation","frontmatter":{"title":"Typescript","description":"Typescript reference documentation"},"headers":[],"relativePath":"knowledge/typescript.md","filePath":"knowledge/typescript.md","lastUpdated":1784485118000}'),o={name:"knowledge/typescript.md"};function n(r,e,c,d,l,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="typescript" tabindex="-1">Typescript <a class="header-anchor" href="#typescript" aria-label="Permalink to &quot;Typescript&quot;">​</a></h1><h1 id="typescript-—-knowledge-reference" tabindex="-1">TypeScript — Knowledge Reference <a class="header-anchor" href="#typescript-—-knowledge-reference" aria-label="Permalink to &quot;TypeScript — Knowledge Reference&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Comprehensive reference for TypeScript development in strict mode. Covers type system fundamentals, advanced patterns, generics, utility types, type narrowing, and module organization. Focused on practical type-safe code for production applications.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="strict-mode-configuration" tabindex="-1">Strict Mode Configuration <a class="header-anchor" href="#strict-mode-configuration" aria-label="Permalink to &quot;Strict Mode Configuration&quot;">​</a></h3><p>Enable <code>strict: true</code> in <code>tsconfig.json</code> to activate all strict type-checking options: <code>strictNullChecks</code>, <code>strictFunctionTypes</code>, <code>strictBindCallApply</code>, <code>noImplicitAny</code>, <code>noImplicitThis</code>, <code>alwaysStrict</code>, <code>useUnknownInCatchVariables</code>, and <code>exactOptionalPropertyTypes</code>. This is non-negotiable for production TypeScript.</p><h3 id="type-inference" tabindex="-1">Type Inference <a class="header-anchor" href="#type-inference" aria-label="Permalink to &quot;Type Inference&quot;">​</a></h3><p>TypeScript infers types from usage. Explicit annotation is needed when inference is insufficient or when you want to enforce a contract. Use <code>satisfies</code> operator (TS 4.9+) to validate types without widening.</p><h3 id="generics" tabindex="-1">Generics <a class="header-anchor" href="#generics" aria-label="Permalink to &quot;Generics&quot;">​</a></h3><p>Generics create reusable, type-safe components. They accept type parameters that preserve type relationships across function signatures, interfaces, and classes. Constraints via <code>extends</code> narrow generic bounds.</p><h3 id="utility-types" tabindex="-1">Utility Types <a class="header-anchor" href="#utility-types" aria-label="Permalink to &quot;Utility Types&quot;">​</a></h3><p>Built-in types that transform other types: <code>Partial&lt;T&gt;</code>, <code>Required&lt;T&gt;</code>, <code>Pick&lt;T, K&gt;</code>, <code>Omit&lt;T, K&gt;</code>, <code>Record&lt;K, V&gt;</code>, <code>Readonly&lt;T&gt;</code>, <code>ReturnType&lt;T&gt;</code>, <code>Parameters&lt;T&gt;</code>, <code>Extract&lt;T, U&gt;</code>, <code>Exclude&lt;T, U&gt;</code>, <code>NonNullable&lt;T&gt;</code>, <code>Awaited&lt;T&gt;</code>.</p><h3 id="type-narrowing" tabindex="-1">Type Narrowing <a class="header-anchor" href="#type-narrowing" aria-label="Permalink to &quot;Type Narrowing&quot;">​</a></h3><p>TypeScript narrows types through control flow: <code>if</code> checks, <code>typeof</code>, <code>instanceof</code>, <code>in</code>, equality checks, truthiness, and custom type guards (<code>x is Type</code>). Discriminated unions narrow via tag properties.</p><h3 id="discriminated-unions" tabindex="-1">Discriminated Unions <a class="header-anchor" href="#discriminated-unions" aria-label="Permalink to &quot;Discriminated Unions&quot;">​</a></h3><p>Sum types where each variant has a common literal property (the discriminant). Pattern matching via switch/if-else on the discriminant gives exhaustive type narrowing.</p><div class="language-typescript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;success&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;error&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">message</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;loading&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> };</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="mapped-types" tabindex="-1">Mapped Types <a class="header-anchor" href="#mapped-types" aria-label="Permalink to &quot;Mapped Types&quot;">​</a></h3><p>Transform existing types by iterating over keys: <code>{ [K in keyof T]: NewType }</code>. Combine with conditionals, modifiers (<code>+readonly</code>, <code>-readonly</code>, <code>+?</code>, <code>-?</code>), and key remapping (<code>as</code>).</p><h3 id="conditional-types" tabindex="-1">Conditional Types <a class="header-anchor" href="#conditional-types" aria-label="Permalink to &quot;Conditional Types&quot;">​</a></h3><p>Type-level if/else: <code>T extends U ? X : Y</code>. Distributes over unions. Used extensively in utility types. <code>infer</code> keyword extracts types within conditional type expressions.</p><h3 id="module-augmentation" tabindex="-1">Module Augmentation <a class="header-anchor" href="#module-augmentation" aria-label="Permalink to &quot;Module Augmentation&quot;">​</a></h3><p>Extend existing module types with <code>declare module &#39;package-name&#39; { ... }</code>. Useful for adding types to third-party libraries or extending global types.</p><h3 id="declaration-files" tabindex="-1">Declaration Files <a class="header-anchor" href="#declaration-files" aria-label="Permalink to &quot;Declaration Files&quot;">​</a></h3><p><code>.d.ts</code> files provide type information for JavaScript modules. <code>@types/</code> packages on npm supply community-maintained declarations. Write declaration files for untyped libraries you consume.</p><h3 id="const-assertions" tabindex="-1">Const Assertions <a class="header-anchor" href="#const-assertions" aria-label="Permalink to &quot;Const Assertions&quot;">​</a></h3><p><code>as const</code> assertion converts literal values to their narrowest type and makes objects/tuples deeply readonly. Essential for literal type preservation in configuration objects and enum-like patterns.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Enable <code>strict: true</code> and never disable it</strong> — strict mode catches real bugs; workarounds create technical debt that compounds over time</li><li><strong>Prefer <code>interface</code> for object shapes and <code>type</code> for unions/intersections</strong> — interfaces merge naturally, support <code>extends</code>, and give clearer errors; types are better for complex compositions</li><li><strong>Use <code>unknown</code> over <code>any</code> for untyped data</strong> — <code>unknown</code> forces type narrowing before use; <code>any</code> disables all type checking</li><li><strong>Leverage discriminated unions for state machines</strong> — model API responses, component states, and domain events as tagged unions for exhaustive handling</li><li><strong>Use <code>satisfies</code> to validate without widening</strong> — <code>const x = { a: 1 } satisfies Record&lt;string, number&gt;</code> preserves literal types while checking structure</li><li><strong>Extract reusable types into dedicated files</strong> — create <code>types/</code> directories for shared domain types, API contracts, and component prop types</li><li><strong>Use branded types for domain primitives</strong> — <code>type UserId = string &amp; { readonly __brand: &#39;UserId&#39; }</code> prevents mixing IDs of different types</li><li><strong>Prefer <code>Pick</code>/<code>Omit</code> over manual type redefinition</strong> — derive types from base types to maintain a single source of truth</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Using <code>any</code> to silence the compiler</strong> — <code>any</code> is a type-checking escape hatch; every <code>any</code> is a potential runtime error</li><li><strong>Repeating type definitions across files</strong> — violates DRY; extract shared types into a centralized types module</li><li><strong>Using type assertions (<code>as</code>) liberally</strong> — assertions bypass type checking; prefer type guards or <code>satisfies</code></li><li><strong>Ignoring TypeScript errors with <code>// @ts-ignore</code></strong> — fix the root cause; <code>@ts-expect-error</code> with explanation is acceptable for documented edge cases only</li><li><strong>Defining overly complex generic types</strong> — if a type definition exceeds 3 lines, simplify or split it</li><li><strong>Not using <code>noUncheckedIndexedAccess</code></strong> — array/object index access can return <code>undefined</code>; enable this option and handle explicitly</li><li><strong>Manually typing everything instead of inferring</strong> — let TypeScript infer when possible; annotate only when needed for contracts or clarity</li><li><strong>Mixing runtime and compile-time types carelessly</strong> — use <code>zod</code> or <code>io-ts</code> for runtime validation; TypeScript types are erased at compile time</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong><code>strictNullChecks</code> not enabled</strong> — the most common source of null/undefined runtime errors; always enable</li><li><strong>Forgetting that <code>interface</code> vs <code>type</code> matters for declarations merging</strong> — <code>interface</code> merges across declarations; <code>type</code> does not</li><li><strong>Using <code>string</code> for IDs instead of branded types</strong> — <code>string</code> is too broad; <code>UserId</code> and <code>PostId</code> should be distinct types</li><li><strong>Over-typing function parameters</strong> — unnecessary type annotations clutter code; infer from usage</li><li><strong>Not handling <code>never</code> type exhaustiveness checks</strong> — add a <code>switch</code> on <code>never</code> in discriminated unions to catch unhandled variants at compile time</li><li><strong>Using <code>Function</code> type</strong> — too vague; use <code>(...args: unknown[]) =&gt; unknown</code> or specific function signatures</li><li><strong>Importing types with <code>import</code> instead of <code>import type</code></strong> — <code>import type</code> ensures zero runtime cost and avoids circular dependency issues</li><li><strong>Not using template literal types for string patterns</strong> — <code>type Route = &#39;/&#39; | &#39;/about&#39; | &#39;/dashboard&#39;</code> catches typos; template literals enable dynamic patterns</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Approach</th></tr></thead><tbody><tr><td>Untyped external data</td><td><code>unknown</code> + type guard or zod schema</td></tr><tr><td>Shared object shape</td><td><code>interface</code></td></tr><tr><td>Union or intersection type</td><td><code>type</code></td></tr><tr><td>Domain primitive (ID, email)</td><td>Branded type</td></tr><tr><td>API response modeling</td><td>Discriminated union</td></tr><tr><td>Configuration object</td><td><code>satisfies</code> + <code>as const</code></td></tr><tr><td>Reusable component props</td><td>Generic type parameters</td></tr><tr><td>Extending third-party types</td><td>Module augmentation or declaration merging</td></tr><tr><td>Runtime validation</td><td>zod/io-ts schema + inferred types</td></tr><tr><td>Null safety</td><td><code>strictNullChecks</code> + optional chaining + nullish coalescing</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://www.typescriptlang.org/docs/handbook" target="_blank" rel="noreferrer">TypeScript Handbook</a></li><li><a href="https://basarat.gitbook.io/typescript" target="_blank" rel="noreferrer">TypeScript Deep Dive</a></li><li><a href="https://www.totaltypescript.com" target="_blank" rel="noreferrer">Total TypeScript</a></li><li><a href="https://github.com/type-challenges/type-challenges" target="_blank" rel="noreferrer">Type Challenges</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><code>tsc --noEmit</code> for type-checking without output; <code>tsc --watch</code> for development</li><li>Use <code>ts-reset</code> for improved built-in type utilities (wider adoption of stricter array/object types)</li><li><code>satisfies</code> was introduced in TypeScript 4.9; ensure your project targets this version or later</li><li>ESLint with <code>@typescript-eslint</code> catches type-related issues beyond what <code>tsc</code> enforces</li><li><code>tsconfig.json</code> paths aliases (<code>@/components/*</code>) improve import ergonomics; pair with build tool configuration</li><li>Consider <code>typeRoots</code> and <code>paths</code> in <code>tsconfig.json</code> for clean import organization</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>`,42)])])}const g=t(o,[["render",n]]);export{y as __pageData,g as default};
